export function metaSalesStepsDueBy(ageInDays: number): MetaSalesStep[] {
  if (ageInDays > META_SALES_WINDOW_DAYS) return [];
  return META_SALES_STEPS.filter((step) => step.day <= ageInDays);
}

export function renderMetaSalesStep(step: MetaSalesStep, unsubscribeUrl: string) {
  const htmlUrl = unsubscribeUrl.replaceAll("&", "&amp;").replaceAll('"', "&quot;");
  return {
    html: step.html.replaceAll("{{{UNSUBSCRIBE_LINK}}}", htmlUrl),
    text: step.text.replaceAll("{{{UNSUBSCRIBE_LINK}}}", unsubscribeUrl),
  };
}
